from pathlib import Path
root=Path(__file__).resolve().parents[1]
h=(root/'Source/GTT/Public/Core/GTTDemoSmokeScenarioSubsystem.h').read_text(encoding='utf-8');cpp=(root/'Source/GTT/Private/Core/GTTDemoSmokeScenarioSubsystem.cpp').read_text(encoding='utf-8');smoke=(root/'Scripts/smoke_test_windows.ps1').read_text(encoding='utf-8');eval_ps=(root/'Scripts/evaluate_demo_scenario.ps1').read_text(encoding='utf-8');demo=(root/'Scripts/evaluate_demo_candidate.ps1').read_text(encoding='utf-8');workflow=(root/'.github/workflows/win64-package-evidence.yml').read_text(encoding='utf-8')
steps=['WORLD','HUD','TRAFFIC','NPC','MISSION','COMBAT','FIELDMASTER','FIELDMASTER_MOTION','FIELDMASTER_CONTROL','RATTLEBACK','RATTLEBACK_MOTION','RATTLEBACK_CONTROL','MULEBOX','MULEBOX_MOTION','MULEBOX_CONTROL','WANTED_COMPONENT','WANTED_ESCALATION','POLICE_RESPONSE','PURSUIT_ACTIVE','PURSUIT_CLOSING','ROADBLOCK_ACTIVE','INTERCEPTION_ACTIVE','SAVE']
checks={'world subsystem':'UTickableWorldSubsystem' in h,'opt-in commandline':'GTTDemoSmokeScenario' in cpp and 'GTTDemoSmokeScenario' in smoke,'explicit 23-step markers':all(f'TEXT("{s}")' in cpp for s in steps) and 'steps=23' in cpp,'native control actuation':all(x in cpp for x in ['SetThrottleInput','SetSteeringInput','SetBrakeInput','DEMO_SCENARIO_CONTROL']),'live wheel motion evidence':all(x in cpp for x in ['GetWheelState','bInContact','NormalizedSuspensionLength','GetVelocity().SizeSquared2D()']),'wanted-4 escalation':'AddHeat(130.f)' in cpp and 'GetWantedLevel()>=4' in cpp,'active police response':'GetActiveFootUnitCount()>0' in cpp,'active pursuit vehicle':'GetActivePursuitVehicleCount()>0' in cpp,'pursuit interaction proof':all(x in cpp for x in ['PursuitStartDistance','Distance+250.f<PursuitStartDistance','PURSUIT_CLOSING']),'roadblock runtime proof':all(x in cpp for x in ['GetActiveRoadblockCount()>0','ROADBLOCK_ACTIVE','DEMO_SCENARIO_ROADBLOCK']),'road-node interception proof':all(x in cpp for x in ['IsRoadNodeInterceptionActive()','GetLastInterceptionNodeLabel()','INTERCEPTION_ACTIVE','DEMO_SCENARIO_INTERCEPTION']),'save is executed':'SaveProgress()' in cpp,'evaluator hard gates':all(s in eval_ps for s in steps) and 'gtt.demo-scenario.v6' in eval_ps,'native spike runtime gate':'ROADBLOCK_SPIKE_CONSEQUENCE vehicle=' in eval_ps and 'path=NATIVE_CHAOS' in eval_ps and 'native_spike_consequence_passed' in eval_ps,'demo gate consumes scenario':"scenario.result -ne 'PASS'" in demo,'workflow order':workflow.index('Evaluate deterministic native roadblock consequence scenario')<workflow.index('Evaluate packaged gameplay smoke'),'artifact retained':'\\DEMO_SCENARIO.json' in workflow,'version':'0.0.89' in workflow}
